#![allow(dead_code)]
mod timing;
use timing::*;
use std::{cell::Cell,panic::{catch_unwind,AssertUnwindSafe},sync::atomic::{AtomicUsize,Ordering}};
struct Token<'a>(&'a Cell<usize>);
impl Drop for Token<'_> { fn drop(&mut self){self.0.set(self.0.get()+1)} }
fn main(){
    let enabled=cfg!(feature="timings");
    assert_eq!(available(),enabled);
    if !enabled {
        assert_eq!(std::mem::size_of::<TimingTrace>(),0);
        assert_eq!(std::mem::size_of::<TimingScope>(),0);
        assert!(!std::mem::needs_drop::<TimingTrace>());
        assert!(!std::mem::needs_drop::<TimingScope>());
    }
    let trace=TimingTrace::new(true);
    let effects=Cell::new(0);let dropped=Cell::new(0);
    let token=trace.value("value",||{effects.set(effects.get()+1);Token(&dropped)});
    assert_eq!(effects.get(),1);assert_eq!(dropped.get(),0);drop(token);assert_eq!(dropped.get(),1);
    let err=trace.measure("error","stage",|child|{assert_eq!(child.report().is_some(),enabled);effects.set(effects.get()+1);Err::<u32,_>("preserve error")});
    assert_eq!(err,Err("preserve error"));
    let panicked=catch_unwind(AssertUnwindSafe(|| trace.value("panic",||{let _token=Token(&dropped);effects.set(effects.get()+1);panic!("CP05 expected probe panic")})));
    assert!(panicked.is_err());assert_eq!(dropped.get(),2);assert_eq!(effects.get(),3);
    {let mut scope=trace.unit_scope("manual","stage",Some(7));scope.finish("ok");scope.finish("wrong second outcome");}
    let calls=AtomicUsize::new(0);
    std::thread::scope(|scope|{for _ in 0..4 {let calls=&calls;let trace=&trace;scope.spawn(move||{trace.value("worker",||{calls.fetch_add(1,Ordering::SeqCst);});});}});
    assert_eq!(calls.load(Ordering::SeqCst),4);
    if let Some(report)=trace.report(){
        assert!(enabled);assert_eq!(report.spans.len(),8);
        assert!(report.spans.iter().all(|s|s.outcome!="running"));
        assert_eq!(report.spans.iter().find(|s|s.name=="error").unwrap().outcome,"error");
        assert_eq!(report.spans.iter().find(|s|s.name=="panic").unwrap().outcome,"panic");
        let manual=report.spans.iter().find(|s|s.name=="manual").unwrap();assert_eq!(manual.outcome,"ok");assert_eq!(manual.unit_index,Some(7));
    }else{assert!(!enabled)}
    println!("{{\"enabled\":{enabled},\"closure_effects\":3,\"drops\":2,\"worker_calls\":4,\"error_preserved\":true,\"panic_preserved\":true}}");
}
